MAP
  NAME "GDALG"
  EXTENT 26.668678 58.339241 26.796582 58.409410
  SIZE 800 600
  IMAGECOLOR "#0A1E50"
  PROJECTION
    "epsg:4326"
  END
  WEB
    IMAGEPATH "/etc/mapserver/tmp/"
    METADATA
      "ows_enable_request" "*"
      "ows_srs" "EPSG:4326 EPSG:3857"
    END
  END

  SYMBOL
    NAME "hatchsymbol"
    TYPE hatch
  END

  LAYER
    NAME "buffered_roads"
    TYPE POLYGON
    STATUS OFF
    CONNECTIONTYPE OGR
    # note we need to use the full path to the dataset using the inline pipeline
    CONNECTION '{"type": "gdal_streamed_alg","command_line": "gdal vector pipeline ! read /etc/mapserver/data/osm/roads.fgb ! buffer --distance=0.0001"}'
    # CONNECTION "data/osm/roads.gdalg.json"
    DATA "0"
    CLASS
      STYLE
        COLOR 50 100 180
      END
      STYLE
        SYMBOL "hatchsymbol"
        COLOR "#78C8FF"
        WIDTH 0.3
        ANGLE 45
        SIZE 8
      END
    END
  END

  # original unbuffered roads dataset
  LAYER
    NAME "roads"
    TYPE LINE
    STATUS OFF
    CONNECTIONTYPE FLATGEOBUF
    DATA "data/osm/roads.fgb"
    CLASS
      STYLE
        WIDTH 0.8
        COLOR "#DCF0FF"
      END
    END
  END

END

